const slots = $slots;
const counts = { red: 0, white: 0 };
for (let index = 0; index < slots.red; index += 1) { counts.red += 1; }
for (let index = 0; index < slots.white; index += 1) { counts.white += 1; }
if (slots.replacement && slots.draws !== slots.red + slots.white) { throw new Error("the replacement draws the count of the outlier"); }
