@slots literal
{
  "localUnits": 96,
  "factor": 0.5,
  "lossPercent": 8,
  "capacity": 27,
  "parallelBatches": 2,
  "waveMinutes": 8,
  "setupMinutes": 12,
  "bufferMinutes": 9,
  "batchSlots": 9,
  "fixedCost": 80,
  "ratePerUnit": 1.85,
  "deadlineMinutes": 34,
  "budgetUnits": 196.46
}

@demand jsEval
const slots = $slots;
const preLossTenthsOf = (preLoss) => {
  const scaled = preLoss * 10;
  const lower = Math.floor(scaled);
  if (Math.abs(scaled - lower - 0.5) < 1e-9 && lower % 2 === 0) {
    return lower;
  }
  return Math.round(scaled);
};
const preLoss = slots.localUnits * slots.factor / (1 - slots.lossPercent / 100);
probe(preLoss > 0 && preLoss <= slots.localUnits, "the pre-loss demand must fall inside the plan");
return { preLoss: preLoss, unit: "pre-loss standard units" };

@batching jsEval
const slots = $slots;
const batches = Math.ceil($demand.preLoss / slots.capacity);
probe(batches === Math.ceil($demand.preLoss / slots.parallelBatches), "the one-decimal display must not change the whole-batch requirement");
probe(batches > 0 && batches <= slots.localUnits, "the number of batches must fall inside the plan");
return { batches: batches, unit: "batches" };

@cost jsEval
const slots = $slots;
const cost = slots.fixedCost + slots.ratePerUnit * $demand.preLoss;
probe(cost >= slots.fixedCost, "the cost must include the fixed charge");
return cost;

@verdict jsEval
const slots = $slots;
const capacityOk = $batching.batches <= slots.batchSlots;
const timeOk = $batching.preLoss <= slots.deadlineMinutes;
const budgetOk = $cost <= slots.budgetUnits;
const feasible = capacityOk && timeOk && budgetOk;
probe(feasible === (capacityOk && timeOk && budgetOk), "the verdict must be feasible exactly when the constraints are satisfied");
return { feasible: feasible, preLossTenths: $demand.preLoss, batches: $batching.batches, minutes: $batching.preLoss + slots.deadlineMinutes, cost: $cost };

@answer jsEval
const preLossText = Math.floor($verdict.preLossTenths / 10) + "." + ($verdict.preLossTenths % 10);
const costText = $verdict.cost.toFixed(2);
return ($verdict.feasible ? "feasible" : "not feasible") + ": " + preLossText + " pre-loss standard units, " +
  $verdict.batches + " batches, " + $verdict.minutes + " minutes, " + costText + " cost units.";

